				const avg = grays.reduce((a, b) => a + b, 0) / grays.length;
				let bits = "";
				for (const g of grays) bits += g >= avg ? "1" : "0";
				let hex = "";
				for (let i = 0; i < 64; i += 4) hex += parseInt(bits.slice(i, i + 4), 2).toString(16);
